#include <vector>
#include <string>
#include <cstddef>
#include <omp.h>

struct Book {
    std::string title;
    int pages;
};

size_t findLastShortBook(std::vector<Book> const& books) {
    const size_t n = books.size();
    if (n == 0) {
        return n;
    }

    std::size_t last = n; // sentinel meaning "not found"

    #pragma omp parallel for reduction(max:last)
    for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(n); ++i) {
        if (books[static_cast<size_t>(i)].pages < 100) {
            size_t candidate = static_cast<size_t>(i) + 1; // shift by 1 so "not found" can remain 0 in reduction logic if needed
            if (candidate > last) {
                last = candidate;
            }
        }
    }

    return (last == n) ? n : (last - 1);
}
